 [],
 [bs("Чия це парасолька?", ["Whose", "umbrella", "is", "this"], ["who", "yours"], "Whose umbrella is this?"),
  fb("It's not my coat. ___ is brown.", ["Mine", "My", "Me"], "Без назви речі — mine."),
  mc("Як сказати «велосипед мого сина»?", ["my son's bike", "my son bike's", "bike my son's"], "My son's bike."),
  tr("Я не можу знайти телефон.", ["I can't find my phone", "I cannot find my phone", "I can't find the phone"], "I can't find my phone."),
  liu("This is our neighbours' dog. Their dog is very noisy.", "Прослухайте. Чий собака?", ["Сусідів", "Наш", "Двоюрідного брата"], "Our neighbours' dog — собака наших сусідів."),
  fb("We have a house. The garden is ___ too.", ["ours", "our", "we"], "Без назви речі — ours."),
  mcu("Хто це: my uncle's daughter?", ["Двоюрідна сестра", "Тітка", "Бабуся"], "Донька дядька — cousin."),
  li("Excuse me, I think this is my bag.", "Ви взяли чужу сумку. Що відповісти?", ["Sorry! It's the same colour.", "Yes, it's mine.", "No, thanks."], "Sorry! It's the same colour — вибачитися й пояснити."),
  tr("Це їхня машина.", ["This is their car", "It's their car", "It is their car"], "This is their car."),
  li("Whose keys are these?", "Це ваші ключі. Що відповісти?", ["They're mine.", "It's my.", "They're me."], "They're mine — про кілька речей.")],
